// Author: MiYu. Bind persistent binary globals, source globals, native calls and callback dispatch.
#include "jass_binary_session.h"
#include <stdexcept>

namespace war3 {
namespace {const JassBinaryProgram& checked(const std::shared_ptr<const JassBinaryProgram>& program){if(!program)throw std::runtime_error("Missing 2SAJ program");return *program;}}
jass::Id JassBinarySession::globalType(const std::string& name,bool array) const{auto& declarations=owner_.module().program().globals();for(size_t i=0;i<declarations.size();++i)if(declarations[i].name==name){auto& slot=owner_.module().globals()[i];if(slot.array!=array)throw std::runtime_error("JASS global shape differs: "+name);return slot.type;}throw std::runtime_error("Unknown JASS global: "+name);}
JassBinarySession::JassBinarySession(jass::Runtime& owner,std::shared_ptr<const JassBinaryProgram> program,const std::string& initializer):owner_(owner),program_(std::move(program)),index_(indexJass2Binary(checked(program_))),storage_(initializeJass2Globals(*program_,index_,initializer)){
    if(!owner_.ready())throw std::runtime_error("2SAJ session requires an initialized JASS owner");host_.nativeArity=[this](const std::string& name){auto id=owner_.module().functionId(name);if(id==jass::none || !owner_.module().program().functions()[id].native)throw std::runtime_error("Unknown 2SAJ native: "+name);return owner_.module().functions()[id].parameters.size();};host_.nativeCall=[this](const std::string& name,auto values){return invokeJass2Native(owner_,*program_,name,values,noYieldDepth_!=0);};host_.globalRead=[this](const std::string& name){return storage_.contains(name)?storage_.read(name):fromJass2Value(owner_,owner_.global(name));};host_.globalWrite=[this](const std::string& name,const JassBinaryNativeValue& value){if(storage_.contains(name))storage_.write(name,value);else owner_.setGlobal(name,toJass2Value(owner_,*program_,globalType(name,false),value));};host_.arrayRead=[this](const std::string& name,std::uint32_t index,std::uint8_t type){auto value=storage_.contains(name)?storage_.readArray(name,index,type):fromJass2Value(owner_,owner_.global(name,index));if(value.type!=type)throw std::runtime_error("2SAJ global array type differs: "+name);return value;};host_.arrayWrite=[this](const std::string& name,std::uint32_t index,const JassBinaryNativeValue& value){if(storage_.contains(name))storage_.writeArray(name,index,value);else owner_.setGlobal(name,toJass2Value(owner_,*program_,globalType(name,true),value),index);};host_.codeReference=[this](const std::string& name){return reference(name);};callbacks_=std::make_unique<JassBinaryCallbacks>(owner_,program_,index_,host_);
}
JassBinarySignature JassBinarySession::signature(const std::string& name) const{
    auto found=index_.functions.find(name);if(found==index_.functions.end())throw std::runtime_error("Unknown 2SAJ function: "+name);auto [start,end]=found->second;auto& instructions=program_->instructions;if(start>=end || end>=instructions.size())throw std::runtime_error("Invalid 2SAJ function bounds");JassBinarySignature result;result.result=instructions[start].r1;if(result.result!=0 && (result.result<3 || result.result>8))throw std::runtime_error("Unsupported 2SAJ result type");size_t count=0;while(start+1+count<end && instructions[start+1+count].opcode==8)++count;result.parameters.resize(count);for(size_t i=0;i<count;++i){auto& arg=instructions[start+1+i];if(arg.r1<3 || arg.r1>8 || !arg.r2 || arg.r2>count || result.parameters[count-arg.r2])throw std::runtime_error("Invalid 2SAJ function signature");result.parameters[count-arg.r2]=arg.r1;}return result;
}
JassBinaryNativeValue JassBinarySession::run(const std::string& name,std::span<const JassBinaryNativeValue> arguments){return runJass2Function(*program_,index_,name,host_,arguments);}
JassBinaryNativeValue JassBinarySession::runNoYield(const std::string& name,std::span<const JassBinaryNativeValue> arguments){++noYieldDepth_;struct Guard{unsigned& depth;~Guard(){--depth;}}guard{noYieldDepth_};return run(name,arguments);}
JassBinaryNativeValue JassBinarySession::reference(const std::string& name){if(!callbacks_)throw std::runtime_error("2SAJ callbacks not initialized");return callbacks_->reference(name);}
}
